-- 391: Original BrillaPrep NSMQ subj_nsmq_physics problem_of_day beta questions (batch 001).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_391_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_391_guard;
INSERT INTO _migration_391_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_pod_b001_001' AND NOT (q.topic_id IS 'topic_kinematics' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A car starts from rest and accelerates uniformly at 4 m/s² for 5 s. How far does it travel?' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS '50 m' AND q.explanation IS 'Use s = ut + ½at² with u = 0, a = 4 m/s² and t = 5 s: s = 0 + ½ × 4 × 5² = 2 × 25 = 50 m. The final speed would be v = u + at = 20 m/s, but the question asks only for distance.' AND q.difficulty IS 'medium' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_pod_b001_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_391_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_pod_b001_002' AND NOT (q.topic_id IS 'topic_electricity' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A 12 V battery is connected across a 4 Ω and an 8 Ω resistor in series. Calculate the power dissipated in the 8 Ω resistor.' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS '8 W' AND q.explanation IS 'Series resistances add: R = 4 + 8 = 12 Ω. Circuit current I = V/R = 12/12 = 1 A, and the same current flows through each resistor in series. Power in the 8 Ω resistor: P = I²R = 1² × 8 = 8 W.' AND q.difficulty IS 'hard' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_pod_b001_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_391_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_pod_b001_003' AND NOT (q.topic_id IS 'topic_thermodynamics' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Calculate the heat required to raise the temperature of 0.5 kg of water from 20 °C to 70 °C. (c = 4200 J/kg°C)' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS '105 000 J (105 kJ)' AND q.explanation IS 'Q = mcΔT with m = 0.5 kg, c = 4200 J/kg°C and ΔT = 70 − 20 = 50 °C: Q = 0.5 × 4200 × 50 = 105 000 J = 105 kJ. Note the temperature change is used, not the final temperature.' AND q.difficulty IS 'medium' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_pod_b001_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_391_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_pod_b001_004' AND NOT (q.topic_id IS 'topic_waves' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A wave covers 340 m in 2.0 s. If its frequency is 85 Hz, what is its wavelength?' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS '2.0 m' AND q.explanation IS 'First find the speed: v = distance/time = 340/2.0 = 170 m/s. Then apply the wave equation v = fλ, so λ = v/f = 170/85 = 2.0 m. Two steps are required: speed from kinematics, then wavelength from the wave relation.' AND q.difficulty IS 'hard' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_pod_b001_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_phys_pod_b001_001', 'topic_kinematics', 'subj_nsmq_physics', 'exam_nsmq', NULL, NULL, 'A car starts from rest and accelerates uniformly at 4 m/s² for 5 s. How far does it travel?', 'problem', 'problem_of_day', NULL, '50 m', 'Use s = ut + ½at² with u = 0, a = 4 m/s² and t = 5 s: s = 0 + ½ × 4 × 5² = 2 × 25 = 50 m. The final speed would be v = u + at = 20 m/s, but the question asks only for distance.', 'medium', '5', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_phys_pod_b001_002', 'topic_electricity', 'subj_nsmq_physics', 'exam_nsmq', NULL, NULL, 'A 12 V battery is connected across a 4 Ω and an 8 Ω resistor in series. Calculate the power dissipated in the 8 Ω resistor.', 'problem', 'problem_of_day', NULL, '8 W', 'Series resistances add: R = 4 + 8 = 12 Ω. Circuit current I = V/R = 12/12 = 1 A, and the same current flows through each resistor in series. Power in the 8 Ω resistor: P = I²R = 1² × 8 = 8 W.', 'hard', '5', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_phys_pod_b001_003', 'topic_thermodynamics', 'subj_nsmq_physics', 'exam_nsmq', NULL, NULL, 'Calculate the heat required to raise the temperature of 0.5 kg of water from 20 °C to 70 °C. (c = 4200 J/kg°C)', 'problem', 'problem_of_day', NULL, '105 000 J (105 kJ)', 'Q = mcΔT with m = 0.5 kg, c = 4200 J/kg°C and ΔT = 70 − 20 = 50 °C: Q = 0.5 × 4200 × 50 = 105 000 J = 105 kJ. Note the temperature change is used, not the final temperature.', 'medium', '5', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_phys_pod_b001_004', 'topic_waves', 'subj_nsmq_physics', 'exam_nsmq', NULL, NULL, 'A wave covers 340 m in 2.0 s. If its frequency is 85 Hz, what is its wavelength?', 'problem', 'problem_of_day', NULL, '2.0 m', 'First find the speed: v = distance/time = 340/2.0 = 170 m/s. Then apply the wave equation v = fλ, so λ = v/f = 170/85 = 2.0 m. Two steps are required: speed from kinematics, then wavelength from the wave relation.', 'hard', '5', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, NULL);
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'nsmq-expansion-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_nsmq_phys_pod_b001_001', 'q_nsmq_phys_pod_b001_002', 'q_nsmq_phys_pod_b001_003', 'q_nsmq_phys_pod_b001_004');
DELETE FROM _migration_391_guard;
INSERT INTO _migration_391_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions WHERE id IN ('q_nsmq_phys_pod_b001_001', 'q_nsmq_phys_pod_b001_002', 'q_nsmq_phys_pod_b001_003', 'q_nsmq_phys_pod_b001_004')) = 4 AND (SELECT COUNT(*) FROM question_content_releases r WHERE r.question_id IN ('q_nsmq_phys_pod_b001_001', 'q_nsmq_phys_pod_b001_002', 'q_nsmq_phys_pod_b001_003', 'q_nsmq_phys_pod_b001_004') AND r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 4 THEN 1 ELSE 0 END;
DROP TABLE _migration_391_guard;
